sql:
SELECT DISTINCT ControllerName
FROM lc_actualcontroller
WHERE ChiName IN ('Wuliangye', 'Zhangyu');

SELECT DISTINCT BusinessMajor
FROM lc_business
WHERE ChiName = 'Jingyan Technology';

SELECT ExImValue AS ImportValue, ExValueOfGoods AS ExportValue
FROM ed_exportimport
WHERE ExImValue > 20000000 AND ExValueOfGoods < 20000000;

SELECT T1.LegalRepr, T1.GeneralManager
FROM lc_stockarchives AS T1
WHERE T1.ChiName = 'Hang Seng Electronics';

SELECT DISTINCT m.FundCode, mf.ChineseName
FROM mf_awards m
JOIN mf_fmtermanalysis mf ON m.FundManager = mf.ChineseName;

SELECT EndDate, GDP
FROM ed_grossdomesticproduct
WHERE Province = 'China' AND EndDate IN (
    SELECT MAX(EndDate) FROM ed_grossdomesticproduct WHERE Province = 'China'
);

SELECT BasisCode, ValueFloor AS MinimumValue, ValueCeiling AS MaximumValue
FROM ed_taxrate
WHERE ItemName = 'Transaction Commission Rate' AND SecuMarket = 'A-share';

SELECT ChiName
FROM mf_assetallocation
WHERE ChiName LIKE '中国资产管理有限公司';

SELECT COUNT(DISTINCT CompanyCode) AS CompanyCount
FROM lc_mainoperincome
WHERE MainOperIncome > 100000000 AND EndDate LIKE '2019-%';

SELECT IssueVolFloor, IssueVolCeiling
FROM lc_ashareseasonednewissue
WHERE SecuCode = '002305' AND IssueVolFloor IS NOT NULL AND IssueVolCeiling IS NOT NULL;

SELECT COUNT(DISTINCT PersonalCode) AS TotalManagers
FROM mf_personalinfo
WHERE Education IN ('Doctor', 'Post-doctoral');

SELECT SHName, SHInvestSum
FROM lc_relatedsh
WHERE SecuCode = '600000' AND SHInvestSum > 10000000;

SELECT DISTINCT ChiName
FROM mf_fundmanagernew
WHERE SecuCode LIKE '15%' AND Performance > 0.7;

SELECT BenchGRForThisWeek
FROM mf_benchmarkgrowthrate
WHERE ChiName = 'China Europe New Trend A';

SELECT COUNT(*) AS RepurchaseCount
FROM lc_buyback
WHERE PlacedYear = '2022';

SELECT CompanyCode, ChiName, ControllerName
FROM lc_actualcontroller
WHERE ChiName = 'Dongfang Electronics';

SELECT COUNT(DISTINCT ChineseName) AS NumberOfManagers
FROM mf_fmtermanalysis
WHERE PracticeDate >= DATE('now', '-1 year');

SELECT DISTINCT SHName
FROM lc_relatedsh
WHERE SecuCode = '000659' AND PlaCode IS NOT NULL;

SELECT AVG(WeightedAvgReturn) AS AverageRateOfReturn
FROM mf_fmretscaleanalysis
WHERE FundTypeName = 'ETF';

SELECT COUNT(DISTINCT SecuCode) AS NumberOfFunds
FROM mf_netvalueperformancehis
WHERE AnnualizedRRSinceStart > 40;

SELECT SUM(IndustrialValueAdded) AS AnnualIndustrialValueAdded
FROM ed_industryproduction
WHERE ReportArea = 'National' AND IndustrialValueAdded IS NOT NULL;

SELECT b.BondCode, b.BondAbbr, b.HoldVolume, b.MarketValue, b.RatioInNV
FROM mf_bondportifoliodetail b
WHERE b.ChiName = 'Fuguo Tianhui A';

SELECT CompanyCode, ChiName, UnderwritingRatio
FROM lc_issueandlistagent
WHERE UnderwritingRatio > 0.01;

SELECT BusinessMajor, MainBusiness, IndustryName
FROM lc_business
WHERE ChiName = '深圳技术';

SELECT DISTINCT ChiName, CompanyCode, TotalShares
FROM lc_sharestru
WHERE TotalShares > 10000000;

SELECT ReportPeriod, RetailValueOfSCGoods
FROM ed_retailvalueofscgoods
WHERE ReportPeriod = '1999' AND ReportArea = 'national' AND (SubjectName = 'State-Owned Units' OR SubjectName = 'Collective Units');

SELECT COUNT(DISTINCT CompanyCode) AS CompanyCount
FROM lc_exgindustry
WHERE FirstIndustryName = 'Real Estate' AND ChiName LIKE '%广东省%';

SELECT MainBusiness
FROM lc_business
WHERE ChiName = 'changshan beiming';

SELECT DISTINCT ChiName
FROM lc_exgindustry
WHERE FirstIndustryName = 'Manufacturing';

SELECT BenchGRFor1Year
FROM mf_benchmarkgrowthrate
WHERE ChiNameAbbr = 'Zhong Ou Growth A';

SELECT DISTINCT ChiName
FROM mf_fundarchives
WHERE Type = 'ETF' AND RiskReturncharacter LIKE '%Medium%';

SELECT COUNT(*) 
FROM ed_chinafibalancesheetrmb 
WHERE CurrencyName NOT IN ('RMB', 'CNY') AND OrgDeposits > 0;

SELECT SubjectName, SubjectSum
FROM ed_newincreasingloan
WHERE ReportPeriod = 'previous year same period';

SELECT COUNT(DISTINCT CompanyCode) AS CompanyCount
FROM lc_financialexpense
WHERE ExchangeProLoss > 10000000;

SELECT ChineseName
FROM mf_fmtermanalysis
WHERE BondFundN = (
    SELECT MAX(BondFundN)
    FROM mf_fmtermanalysis
);

SELECT DISTINCT TradingDay
FROM qt_dailyquote
WHERE SecuCode = '300770' AND TurnoverDeals > 5000;

SELECT MIN(IssueVol) AS MinIssuanceVolume, MAX(IssueVol) AS MaxIssuanceVolume
FROM lc_ashareseasonednewissue
WHERE SecuCode = '002305';

SELECT COUNT(*) 
FROM lc_buyback 
WHERE BuybackMoney > 100000000;

SELECT QDIINV AS QDII_Size, MonetaryFundNV AS Monetary_Fund_Size
FROM mf_fmscaleanalysisn
WHERE ChineseName = 'Liu Gesong';

SELECT InvestmentType
FROM mf_fundarchives
WHERE ChiName = 'Invesco Resources';

SELECT DISTINCT mf_awards.FundManager
FROM mf_awards
WHERE mf_awards.Year = 'last year';

SELECT DISTINCT FundCompany
FROM mf_awards
WHERE Year = 'last year';

SELECT ChineseName, BondFundN
FROM mf_advisorscalerank
WHERE BondFundN = (
    SELECT MAX(BondFundN) FROM mf_advisorscalerank
);

SELECT DISTINCT fm.ChineseName
FROM mf_fmscaleanalysisn fm
WHERE fm.TotalFundNV > 2000;

SELECT DISTINCT FundTypeName, RRInSelectedWeek AS WeeklyReturnRate
FROM mf_netvalueperformancehis
WHERE TimeInterval = 'Weekly';

SELECT COUNT(DISTINCT CompanyCode) AS CompanyCount
FROM lc_mainoperincome
WHERE MainOperIncome > 100000000 AND EndDate LIKE '2022-%';

SELECT IndexValue
FROM ed_producerpiformp
WHERE IndexName = 'Industrial Structure Classification Index' AND ReportPeriod = 'Same Month Last Year' AND IndexType = 'Living Materials';

SELECT TotalRDInput
FROM lc_intassetsdetail
WHERE ChiName = 'Shenzhen Technology' AND EndDate = '2017';

SELECT DISTINCT mfa.FundName, mwa.AwardName
FROM mf_awards mwa
JOIN mf_fundarchives mfa ON mwa.Fund = mfa.SecuAbbr;

SELECT SUM(RetailValueOfSCGoods) AS TotalRetailSales
FROM ed_retailvalueofscgoods
WHERE WholesaleRetailTrade = '1' AND StateOwnedUnits = '1';

SELECT DISTINCT SponsorName
FROM lc_ipodeclaration
WHERE SecuCode = '603806';

SELECT DISTINCT PlaObject
FROM lc_asharereplacement
WHERE PlaYear = '2013';

SELECT SecuCode
FROM lc_sharefpsta
WHERE ChiName = 'Lao Feng Xiang';

SELECT DISTINCT l.SecuCode, l.ChiName
FROM lc_dividend l
WHERE l.DiviBase > 10000000;

SELECT BenchGRFor6Month
FROM mf_benchmarkgrowthrate
WHERE ChiName = 'E Fund Non-Bank ETF';

SELECT lsl.SHName AS MajorShareholder
FROM lc_largeshsubscription lsl
WHERE lsl.ChiName = '广州朗启';

SELECT COUNT(*) AS TotalIssuances
FROM lc_ashareseasonednewissue
WHERE IssueStartDate LIKE '2022-%';

SELECT DISTINCT SecuCode
FROM lc_mainoperincome
WHERE GrossProfit > 1;

SELECT OrganizationForm
FROM mf_investadvisoroutline
WHERE ChiName = 'Changxin Fund';

SELECT ed_moneyauthoritybs.EndDate, ed_moneyauthoritybs.MoneyAndGold
FROM ed_moneyauthoritybs
WHERE ed_moneyauthoritybs.EndDate = 'your_specific_date';

SELECT AStockCode
FROM lc_stockarchives
WHERE ChiName = '工业证券';

SELECT EndDate, TotalLiability
FROM ed_otherdepositorycorpbs
WHERE TotalLiability >= 50 AND EndDate >= '2009-01-01';

SELECT AnnualizedRRSinceStart
FROM mf_netvalueperformancehis
WHERE SecuCode = 'your_fund_code_here';

SELECT SHName, HoldingSum
FROM lc_relatedsh
WHERE CompanyName = 'Baichuan' AND EndDate BETWEEN '2020-07-01' AND '2020-09-30';

SELECT InvestTarget
FROM mf_fundarchives
WHERE ChiName = 'ChinaAMC Resources Fund';

SELECT ReportPeriod, IndustrialValueAdded
FROM ed_industryproduction
WHERE ReportArea = 'National' AND StatStandard = 'State-owned and above-scale industrial enterprises' AND EndDate < '1999-01-01';

SELECT SUM(Forex) AS TotalForeignCurrencyDeposits
FROM ed_moneyauthoritybs
WHERE EndDate = DATE('now', '-2 year');

SELECT COUNT(DISTINCT CompanyCode) AS CompanyCount
FROM lc_sharesfloatingschedule
WHERE Proportion2 > 80;

SELECT DISTINCT LawFirm, AccountingFirm
FROM lc_ipodeclaration
WHERE ChiName = 'JiKai Corporation';

SELECT StDivStand1, EnDivStand1
FROM mf_chargeratenew
WHERE SecuAbbr = 'Taipingdale Zhongzheng 500' AND ChiName = 'Front-end Direct Sales Counter';

SELECT SUM(UnderwritingVol) AS Total_Underwriting_Volume
FROM lc_issueandlistagent
WHERE ChiName = ' Yue Gao Su ';

SELECT SUM(BuybackSum) AS TotalRepurchaseQuantity, SUM(BuybackMoney) AS TotalRepurchasePrice
FROM lc_buyback
WHERE SecuCode = '600418' AND BuybackPrice IS NOT NULL AND Date(AdvanceDate) >= Date('now', '-1 year');

SELECT DISTINCT ConceptName
FROM lc_coconcept
WHERE SecuCode = '000021';

SELECT DISTINCT ChiName, ChiNameAbbr
FROM lc_sharestru
WHERE NonRestrictedShares <= 50000000 AND RestrictAShareP = 0;

SELECT MonthlyBenchGR
FROM mf_benchmarkgrowthrate
WHERE SecuCode = '162415';

SELECT COUNT(*) AS ConventionalFundCount
FROM mf_fundarchives
WHERE FundType = 'LOF' AND FundNature LIKE '%Conventional%';

SELECT IFInitiatingFund 
FROM mf_fundarchives 
WHERE ChiName = '中国民生增长';

SELECT COUNT(DISTINCT ChiName) AS ListedCompanyCount
FROM lc_stockarchives
WHERE State = '上海';

SELECT COUNT(*) AS QDII_Fund_Count
FROM mf_fundarchives
WHERE FundType = 'QDII' AND ChiName = 'Bosera Gold';

SELECT SUM(OtherForeignAssets) AS TotalForeignAssets
FROM ed_otherdepositorycorpbs
WHERE EndDate = 'YourSpecificEndDate';

SELECT MIN(RatioFloor) AS MinExcessReserveRequirementRatio
FROM fm_depositreserveratio
WHERE DRRType = 'Excess Reserve Requirement Ratio';

SELECT DISTINCT ChiName, ChiNameAbbr, SecuCode
FROM mf_benchmarkgrowthrate
WHERE BenchGRForThisWeek > 5;

SELECT DISTINCT ChiName
FROM lc_stockarchives
WHERE GeneralManager LIKE '刘%';

SELECT COUNT(DISTINCT SHNum) AS TotalShareholders
FROM lc_shnumber
WHERE ChiName = 'DongE EJiao' AND EndDate LIKE '2019-01-%';

SELECT COUNT(DISTINCT Type) AS NumberOfFunds
FROM mf_fundarchives
WHERE Type LIKE 'Mutual Recognition Fund';

SELECT COUNT(*) AS TotalFunds
FROM mf_fmscaleanalysisn
WHERE ChineseName = 'Zhang Kun';

SELECT DISTINCT ChiName
FROM lc_business
WHERE IndustryName = '纺织业';

SELECT StDivStand1, EnDivStand1
FROM mf_chargeratenew
WHERE ChiName = 'Daily Redemption Fee - Onshore' AND InnerCode = 160133;

SELECT SUM(StateOwnedControlledComAP + CollectiveComAP) AS AccumulatedIndustrialProductionValue
FROM ed_industryproduction
WHERE ReportArea = 'the whole country' AND EndDate = '1999';

SELECT DISTINCT SecuCode
FROM lc_business
WHERE CSRCIndustryName = 'liquor';

SELECT COUNT(*) AS ETFCount
FROM mf_advisorscalerank
WHERE FundTypeName = 'ETF';

SELECT DISTINCT ChiName
FROM lc_mainoperincome
WHERE MainOperCost > 100000000;

SELECT RegAddr, RegCapital
FROM mf_investadvisoroutline
WHERE TrusteeName = 'China-Europe Fund';

SELECT SecuCode, AnnualizedRRInFiveYear
FROM mf_netvalueperformancehis
WHERE AnnualizedRRInFiveYear IS NOT NULL;
